scwin.trigger1_onclick = function(e) {
    //alert("123");
    showAlert = true;
};
scwin.__buttonNotDisappeared = function() {
    var button = ((j) => j.length ? j : $('#mf_trigger1'))($('#trigger1'));
    if (!button.length) {
        return false;
    }
    return button.get(0).nodeName == "A";
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.showAlert = false;
}
